"""Migration of legacy/order_totals.crms."""

from decimal import Decimal, ROUND_HALF_UP, localcontext


_CENTS = Decimal("0.01")


def _number(value) -> Decimal:
    """Apply legacy NVL(x, 0) numeric behavior without float artifacts."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, float):
        return Decimal(str(value))
    return Decimal(str(value))


def _cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    """Recompute one order's live line extensions and discounted total."""
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    with localcontext() as context:
        context.prec = 50
        total = Decimal(0)

        for original_line, new_line in zip(lines, new_lines):
            if original_line.get("DEL_FLG") == "Y":
                continue

            ext = _cents(_number(original_line.get("QTY")) *
                         _number(original_line.get("UNIT_PRC")))
            new_line["EXT_AMT"] = float(ext)
            total += ext

        discounted = _cents(
            total * (Decimal(100) - _number(order.get("DISC_PCT"))) / Decimal(100)
        )

    if _number(order.get("TOT_AMT")) != discounted:
        new_order["TOT_AMT"] = float(discounted)
        return new_order, new_lines, [("ORD_RETOTAL", order.get("ORD_ID"))]

    return new_order, new_lines, []
